item.content:encoded:
/* GeneratePress Site CSS */ /* Primary navigation style */
@media (min-width: 769px) {
.inside-navigation {
	border: 1px solid var(--accent);
  box-shadow: inset 3px 3px 8px 3px RGB(0 0 0 / 0.4);
}
}
.header-wrap .main-navigation.toggled .main-nav {
    background-color: var(--base-3);
}
.shadow-headline {
	text-shadow: rgb(0 0 0 / 50%) 5px 5px 10px;
}
.shadow-container {
		box-shadow: rgb(0 0 0 / 50%) 5px 5px 10px;
}
@media (min-width: 769px) {
.project-introduction {
	  transition: all 0.5s ease;
	  opacity:0;
	  transform: translatey(20px);
}
.project:hover .project-introduction {
    opacity: 1;
	  transform: translatey(0);
}
}
/* Forceer tekst zichtbaarheid tijdens laden */
@font-face {
  font-family: 'Lato';
  font-display: swap !important;
}
/* Alleen animeren op schermen breder dan 768px */
@media (min-width: 769px) {
    .vs-text-shimmer {
        animation: vs-text-shimmer 6s linear infinite;
    }
    .vs-fire-roll {
        animation: vs-fire-roll 6s linear infinite;
    }
}


 /* End GeneratePress Site CSS */

